import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and its </title> in html.

    Tag names match case-insensitively, and a <title> tag may carry
    attributes. The result is stripped of surrounding whitespace. Returns
    an empty string when there is no complete title element. The html
    argument is already-fetched text; this function never performs I/O.
    """
    match = re.search(
        r"<title(?:\s[^>]*)?>(.*?)</title\s*>",
        html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if match is None:
        return ""
    body: str = match.group(1)
    return body.strip()


def test_title_of_simple() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_of_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Shout</Title></HTML>") == "Shout"


def test_title_of_with_attributes() -> None:
    assert title_of('<title lang="en">Bonjour</title>') == "Bonjour"


def test_title_of_strips_whitespace() -> None:
    assert title_of("<title>\n  Spaced out  \n</title>") == "Spaced out"


def test_title_of_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_title_of_missing_title_returns_empty() -> None:
    assert title_of("<html><body>no head here</body></html>") == ""


def test_title_of_unclosed_title_returns_empty() -> None:
    assert title_of("<title>never closed") == ""


def test_title_of_empty_input_returns_empty() -> None:
    assert title_of("") == ""
